def process(loadMsaIdentityTheft2024) -> pd.DataFrame:
    import pandas as pd

    df = loadMsaIdentityTheft2024.copy()

    cols = list(df.columns)
    # Find the metro area/name column
    area_col = None
    for c in cols:
        if isinstance(c, str) and ("Metropolitan" in c or "Metropolitan Areas" in c):
            area_col = c
            break
    if area_col is None:
        area_col = cols[0]

    # Find reports column (prefer the typical 'Unnamed: 1')
    reports_col = None
    for c in cols:
        if c != area_col and isinstance(c, str) and ("Reports" in c or "Unnamed" in c):
            reports_col = c
            break
    if reports_col is None:
        reports_col = cols[1] if len(cols) > 1 else cols[0]

    out = df[[area_col, reports_col, "_source_file"]].rename(
        columns={area_col: "metropolitan_area", reports_col: "reports"}
    )

    area = out["metropolitan_area"].astype("string").fillna("").str.strip()
    bad_area = (
        area.eq("")
        | area.str.match(r"(?i)^source:")
        | area.str.match(r"(?i)^metropolitan areas?:")
        | area.eq("Metropolitan Area")
    )
    out = out.loc[~bad_area].copy()

    rep_str = out["reports"].astype("string").str.replace(",", "", regex=False).str.strip()
    rep_str = rep_str.replace(
        {
            "": pd.NA,
            "NA": pd.NA,
            "N/A": pd.NA,
            "--": pd.NA,
            "nan": pd.NA,
            "# of Reports": pd.NA,
        }
    )
    out["reports"] = pd.to_numeric(rep_str, errors="coerce")
    out = out[out["reports"].notna()].copy()

    return out.reset_index(drop=True)

def process(loadMsaIdentityTheft2024) -> pd.DataFrame:
    import pandas as pd

    df = loadMsaIdentityTheft2024.copy()

    # robust column picking
    cols = list(df.columns)
    area_col = None
    for c in cols:
        if isinstance(c, str) and ("Metropolitan" in c or "Metropolitan Areas" in c):
            area_col = c
            break
    if area_col is None:
        area_col = cols[0]

    # pick a likely reports column: prefer explicit '# of Reports' row label column name like 'Unnamed: 1'
    candidates = [c for c in cols if c != area_col]
    reports_col = None
    for c in candidates:
        if isinstance(c, str) and (c.strip().lower() in {"# of reports", "reports"}):
            reports_col = c
            break
    if reports_col is None:
        for c in candidates:
            if isinstance(c, str) and c.lower().startswith("unnamed"):
                reports_col = c
                break
    if reports_col is None and candidates:
        reports_col = candidates[0]

    out = df[[area_col, reports_col, "_source_file"]].rename(
        columns={area_col: "metropolitan_area", reports_col: "reports"}
    )

    # drop non-data rows
    area = out["metropolitan_area"].astype("string")
    areaNorm = area.fillna("").str.strip()
    bad_area = (
        areaNorm.eq("")
        | areaNorm.str.match(r"(?i)^source:")
        | areaNorm.str.match(r"(?i)^metropolitan areas?:")
        | areaNorm.eq("Metropolitan Area")
    )
    out = out.loc[~bad_area].copy()

    # numeric parse
    rep_str = out["reports"].astype("string").str.replace(",", "", regex=False).str.strip()
    rep_str = rep_str.replace({"": pd.NA, "NA": pd.NA, "N/A": pd.NA, "--": pd.NA, "nan": pd.NA})
    out["reports"] = pd.to_numeric(rep_str, errors="coerce")

    out = out[out["reports"].notna()].copy()

    return out.reset_index(drop=True)
